# region: emit
def emit(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: fold
def fold(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: shape
def shape(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: render
def render(xs, cut=8):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs) - 1, 'lo': len(lo), 'hi': len(hi)}

# region: digest
def digest(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return digest(render(shape(fold(emit(raw)))))

